extern "C" const b3HeightFieldData* cpu_b3Shape_GetHeightField(b3ShapeId) __attribute__((weak));
static void heightfield_details(FILE* f,const b3HeightFieldData* h){if(!h){std::fputs("null",f);return;}int cells=(h->rowCount-1)*(h->columnCount-1),holes=0;auto* material=b3GetHeightFieldMaterialIndices(h);for(int i=0;i<cells;++i)if(material[i]==B3_HEIGHT_FIELD_HOLE)++holes;std::fprintf(f,"{\"rows\":%d,\"columns\":%d,\"hash\":\"%016llx\",\"scale\":",h->rowCount,h->columnCount,(unsigned long long)h->hash);shape_vec(f,h->scale);std::fprintf(f,",\"holes\":%d,\"height_range\":[%.9g,%.9g],\"bounds\":[",holes,h->minHeight,h->maxHeight);shape_vec(f,h->aabb.lowerBound);std::fputc(',',f);shape_vec(f,h->aabb.upperBound);std::fputs("]}",f);}
